269	pub(crate) fn type_hint_resolves_to_any(
270	    annotation: &Expr,
271	    checker: &Checker,
272	    version: ast::PythonVersion,
273	) -> bool {
274	    match TypingTarget::try_from_expr(annotation, checker, version) {
275	        // Short circuit on top level `Any`
276	        None | Some(TypingTarget::Any) => true,
277	        // `Optional` is `Optional[Any]` which is `Any | None`.
278	        Some(TypingTarget::Optional(None)) => true,
279	        // Top-level `Annotated` node should check if the inner type resolves
280	        // to `Any`.
281	        Some(TypingTarget::Annotated(expr)) => {
282	            expr.is_some_and(|expr| type_hint_resolves_to_any(expr, checker, version))
283	        }
284	        Some(target) => target.contains_any(checker, version),
285	    }
286	}
